"  useEffect(() => {
    if (!previewReceipt || !posSettings.printUpiQr) {
      setPreviewQrUrl(null);
      setPreviewQrMeta(null);
      return;
    }
    const payeeName = business?.business_name || business?.name || posSettings.receiptHeader || 'SHAHE TEHZEEB RESTAURANT';

    if (posSettings.qrMode === 'static') {
      const activeEntry = (posSettings.staticUpiList || []).find(e => e.id === posSettings.activeStaticUpiId);
      if (!activeEntry) { setPreviewQrUrl(null); setPreviewQrMeta(null); return; }
      const upiUri = `upi://pay?pa=${activeEntry.upiId}&pn=${encodeURIComponent(payeeName)}&cu=INR`;
      QRCode.toDataURL(upiUri, { margin: 1, width: 140 })
        .then(url => { setPreviewQrUrl(url); setPreviewQrMeta({ upiId: activeEntry.upiId, brand: activeEntry.brand, name: activeEntry.name }); })
        .catch(err => console.error('Failed to generate preview QR:', err));
    } else {
      if (!posSettings.upiId) { setPreviewQrUrl(null); setPreviewQrMeta(null); return; }
      const upiAmount = parseFloat(previewReceipt.total_price || 0).toFixed(2);
      const upiUri = `upi://pay?pa=${posSettings.upiId}&pn=${encodeURIComponent(payeeName)}&am=${upiAmount}&cu=INR`;
      QRCode.toDataURL(upiUri, { margin: 1, width: 120 })
        .then(url => { setPreviewQrUrl(url); setPreviewQrMeta({ upiId: posSettings.upiId, brand: null, name: null }); })
        .catch(err => console.error('Failed to generate preview QR:', err));
    }
  }, [previewReceipt, posSettings.printUpiQr, posSettings.upiId, posSettings.qrMode, posSettings.activeStaticUpiId, posSettings.staticUpiList, business]);"
